package com.example.Kcsj;

import com.example.Kcsj.membership.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
import org.springframework.http.HttpMethod;
import org.springframework.mock.web.MockMultipartFile;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static com.example.Kcsj.membership.MemberStore.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:life-tests;DB_CLOSE_DELAY=-1","shuyang.admin-password=","shuyang.data-key="})
@AutoConfigureMockMvc
class LifeServicesTests {
    @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired MemberStore store;@Autowired MemberAuth auth;@Autowired JdbcTemplate jdbc;
    Map<String,Object> owner,helper,other,admin,organizer,moderator,pending;
    @BeforeEach void setup(){jdbc.update("DELETE FROM syh_record");jdbc.update("DELETE FROM syh_session");jdbc.update("DELETE FROM syh_attachment");owner=person("member",true);helper=person("member",true);other=person("member",true);admin=person("superadmin",true);organizer=person("organizer",true);moderator=person("moderator",true);pending=person("member",false);}
    Map<String,Object> person(String role,boolean approved){Map<String,Object>p=map("id",id(),"name","验收老乡","role",role,"status",approved?"approved":"pending","enabled",true,"directoryVisible",true);store.save("user",p);p.put("token",auth.session(p).get("token"));return p;}
    @SuppressWarnings("unchecked") Map<String,Object> call(String method,String path,Map<String,Object>actor,Object body,int code)throws Exception{MockHttpServletRequestBuilder b=request(HttpMethod.valueOf(method),path);if(actor!=null)b.header("Authorization","Bearer "+s(actor,"token"));if(body!=null)b.contentType("application/json").content(json.writeValueAsBytes(body));String raw=mvc.perform(b).andExpect(status().is(code)).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8);return json.readValue(raw,Map.class);}
    @SuppressWarnings("unchecked") Map<String,Object> data(Map<String,Object>result){return (Map<String,Object>)result.get("data");}
    @SuppressWarnings("unchecked") List<Map<String,Object>> list(String path,Map<String,Object>actor)throws Exception{return (List<Map<String,Object>>)call("GET",path,actor,null,200).get("data");}
    Map<String,Object> form(String type){return map("type",type,"requestId",id(),"title","验收服务事项","content","这是隔离环境中的验收内容，不是真实发布。","region","苏州吴中","category","服务验收","deadline",LocalDate.now(ZoneId.of("Asia/Shanghai")).plusDays(7).toString(),"method","线上","photos",Collections.emptyList());}
    Map<String,Object> create(String type,Map<String,Object>a)throws Exception{return data(call("POST","/life/entries",a,form(type),200));}
    Map<String,Object> entry(Map<String,Object>r,Map<String,Object>a)throws Exception{return data(call("GET","/life/entries/"+s(r,"id"),a,null,200));}
    void action(Map<String,Object>r,Map<String,Object>a,String action,int code)throws Exception{call("POST","/life/entries/"+s(r,"id")+"/action",a,map("action",action,"note","验收处理说明"),code);}
    Map<String,Object> apply(Map<String,Object>r,Map<String,Object>a)throws Exception{return data(call("POST","/life/entries/"+s(r,"id")+"/apply",a,map("message","未公开的核验特征和自我介绍"),200));}
    void appAction(Map<String,Object>r,Map<String,Object>a,String action,int code)throws Exception{call("POST","/life/applications/"+s(r,"id")+"/action",a,map("action",action,"note","验收处理结果"),code);}
    Map<String,Object> approvedHelp()throws Exception{Map<String,Object>r=create("help",owner);action(r,admin,"approve",200);return entry(r,owner);}
    Map<String,Object> slot(int capacity)throws Exception{Map<String,Object>f=form("slot");f.putAll(map("startsAt",Instant.now().plusSeconds(3600).toString(),"endsAt",Instant.now().plusSeconds(7200).toString(),"capacity",capacity));return data(call("POST","/life/entries",admin,f,200));}
    Map<String,Object> order(Map<String,Object>a){Map<String,Object>r=map("id",id(),"buyerId",s(a,"id"),"delivery","pickup","status","ready","settlement","unconfirmed","title","验收家乡特产","orderNo",id(),"quantity",1);store.save("order",r);return r;}
    void reserve(Map<String,Object>o,Map<String,Object>s,Map<String,Object>a,int code)throws Exception{call("POST","/life/pickup/reserve",a,map("orderId",o.get("id"),"slotId",s.get("id")),code);}
    @Test void memberAndModerationPermissionsAreEnforced()throws Exception{call("POST","/life/entries",null,form("help"),401);call("POST","/life/entries",pending,form("help"),403);Map<String,Object>r=create("help",owner);assertTrue(list("/life/entries?type=help",null).isEmpty());call("GET","/life/entries/"+s(r,"id"),other,null,404);action(r,moderator,"approve",403);action(r,organizer,"approve",200);assertEquals(1,list("/life/entries?type=help",null).size());call("GET","/life/entries?type=help&scope=manage",other,null,403);}
    @Test void submissionRetryDoesNotDuplicateAndEditReturnsToReview()throws Exception{Map<String,Object>f=form("help"),a=data(call("POST","/life/entries",owner,f,200)),b=data(call("POST","/life/entries",owner,f,200));assertEquals(a.get("id"),b.get("id"));action(a,admin,"approve",200);f.putAll(map("id",a.get("id"),"revision",1));call("POST","/life/entries",owner,f,409);f.put("revision",entry(a,owner).get("revision"));Map<String,Object>changed=data(call("POST","/life/entries",owner,f,200));assertEquals("pending",changed.get("status"));}
    @Test void helpRequiresOwnerConfirmationAndKeepsApplicationsPrivate()throws Exception{Map<String,Object>r=approvedHelp(),app=apply(r,helper);assertTrue(list("/life/entries/"+r.get("id")+"/applications",other).isEmpty());appAction(app,owner,"accept",200);appAction(app,helper,"outcome",200);action(r,helper,"resolve",403);action(r,admin,"resolve",409);action(r,owner,"resolve",200);assertEquals("resolved",entry(r,owner).get("status"));appAction(app,helper,"outcome",403);}
    @Test void secondAcceptedHelperCannotReplaceFirst()throws Exception{Map<String,Object>r=approvedHelp(),a=apply(r,helper),b=apply(r,other);appAction(a,owner,"accept",200);appAction(b,owner,"accept",409);assertEquals(a.get("id"),store.get("life_entry",s(r,"id")).get("selectedApplicationId"));}
    @Test void helperReleaseRequiresExplicitOwnerOrAdminCoordination()throws Exception{Map<String,Object>r=approvedHelp(),a=apply(r,helper);appAction(a,owner,"accept",200);action(r,owner,"release",403);appAction(a,helper,"request-release",200);action(r,organizer,"coordinate",403);action(r,owner,"release",200);assertEquals("open",entry(r,owner).get("status"));assertEquals("released",store.get("life_application",s(a,"id")).get("status"));}
    @Test void expiredAndPausedJobsCannotReceiveIntent()throws Exception{Map<String,Object>f=form("job");f.putAll(map("employer","验收用工单位","salary","面议","schedule","每周五天八小时","employment","全职","publisher","企业直招","benefits",""));Map<String,Object>r=data(call("POST","/life/entries",owner,f,200));action(r,admin,"approve",200);action(r,owner,"pause",200);call("POST","/life/entries/"+r.get("id")+"/apply",helper,map("message","希望了解岗位"),409);action(r,owner,"resume",200);r=store.get("life_entry",s(r,"id"));r.put("deadline","2020-01-01");store.save("life_entry",r);call("POST","/life/entries/"+r.get("id")+"/apply",helper,map("message","希望了解岗位"),409);}
    @Test void guideChecklistIsPrivateAndRejectsStaleItems()throws Exception{Map<String,Object>f=form("guide");f.putAll(map("sourceName","官方办事入口","sourceUrl","https://www.suzhou.gov.cn/","verifiedOn",LocalDate.now().toString(),"checklistText","确认适用地区\n查阅办理条件"));call("POST","/life/entries",owner,f,403);Map<String,Object>r=data(call("POST","/life/entries",admin,f,200));String path="/life/entries/"+r.get("id")+"/checklist";call("POST",path,owner,map("checked",Arrays.asList("确认适用地区")),200);assertTrue(((List<?>)data(call("GET",path,helper,null,200)).get("checked")).isEmpty());call("POST",path,owner,map("checked",Arrays.asList("伪造材料")),409);assertEquals(1,store.all("life_checklist").size());}
    @Test void guideRejectsDangerousSourceAndInvalidDate()throws Exception{Map<String,Object>f=form("guide");f.putAll(map("sourceName","资料来源","sourceUrl","javascript:alert(1)","verifiedOn","2026-11-02","checklistText","查看条件"));call("POST","/life/entries",admin,f,400);f.put("sourceUrl","https://name:password@example.com");call("POST","/life/entries",admin,f,400);f.put("sourceUrl","https://www.suzhou.gov.cn");f.put("verifiedOn","2030-22-45");call("POST","/life/entries",admin,f,400);}
    @Test void serviceVisibilityFollowsDirectoryConsent()throws Exception{Map<String,Object>f=form("service");f.putAll(map("availability","周末下午","pricing","公益咨询，免费"));Map<String,Object>r=data(call("POST","/life/entries",owner,f,200));action(r,admin,"approve",200);assertTrue(list("/life/entries?type=service",null).isEmpty());assertEquals(1,list("/life/entries?type=service",helper).size());Map<String,Object>u=store.get("user",s(owner,"id"));u.put("directoryVisible",false);store.save("user",u);call("GET","/life/entries/"+r.get("id"),helper,null,404);}
    @Test void acceptedServiceIntentCanBeWithdrawn()throws Exception{Map<String,Object>f=form("service");f.putAll(map("availability","周末下午","pricing","公益咨询，免费"));Map<String,Object>r=data(call("POST","/life/entries",owner,f,200));action(r,admin,"approve",200);Map<String,Object>a=apply(r,helper);appAction(a,owner,"accept",200);appAction(a,helper,"withdraw",200);assertEquals("withdrawn",store.get("life_application",s(a,"id")).get("status"));}
    @Test void reusedSubmissionKeyRejectsDifferentContent()throws Exception{Map<String,Object>f=form("help");call("POST","/life/entries",owner,f,200);f.put("title","另一个不同的请求");call("POST","/life/entries",owner,f,409);}
    @Test void lostClaimsAreNeverPartOfPublicEntry()throws Exception{Map<String,Object>f=form("lost");f.putAll(map("lostType","招领","occurredOn",LocalDate.now().toString()));Map<String,Object>r=data(call("POST","/life/entries",owner,f,200));action(r,admin,"approve",200);Map<String,Object>a=apply(r,helper);assertFalse(json.writeValueAsString(entry(r,null)).contains("未公开的核验特征"));appAction(a,owner,"accept",200);action(r,owner,"close",200);assertEquals("closed",entry(r,null).get("status"));}
    @Test void notificationsArePrivateReadDoesNotCompleteBusiness()throws Exception{Map<String,Object>r=approvedHelp();apply(r,helper);List<Map<String,Object>>messages=list("/life/notifications",owner);assertFalse(messages.isEmpty());assertTrue(list("/life/notifications",other).isEmpty());call("POST","/life/notifications/read",other,map("id",messages.get(0).get("id")),200);assertFalse(b(store.get("business_notice",s(messages.get(0),"id")),"read"));call("POST","/life/notifications/read",owner,map("id","all"),200);assertEquals("open",entry(r,owner).get("status"));}
    @Test void unsubscribeStopsFurtherUpdates()throws Exception{Map<String,Object>r=approvedHelp();String path="/life/entries/"+r.get("id")+"/subscribe";call("POST",path,helper,map("active",true),200);action(r,owner,"pause",200);int count=list("/life/notifications",helper).size();assertTrue(count>0);call("POST",path,helper,map("active",false),200);action(r,owner,"resume",200);assertEquals(count,list("/life/notifications",helper).size());}
    @Test void feedbackIsPrivateAndAdminResponseIsAudited()throws Exception{Map<String,Object>r=approvedHelp(),f=data(call("POST","/life/entries/"+r.get("id")+"/feedback",helper,map("message","信息有误请核对一下"),200));assertTrue(list("/life/feedback",other).isEmpty());call("POST","/life/feedback/"+f.get("id"),organizer,map("reply","已核对"),403);call("POST","/life/feedback/"+f.get("id"),admin,map("reply","已核实并更正"),200);assertEquals("resolved",list("/life/feedback",helper).get(0).get("status"));}
    @Test void pickupCapacityIdempotencyAndCancellation()throws Exception{Map<String,Object>s=slot(1),a=order(owner),b=order(helper);reserve(a,s,owner,200);reserve(a,s,owner,200);reserve(b,s,helper,409);call("POST","/life/pickup/"+a.get("id")+"/cancel",helper,map(),403);call("POST","/life/pickup/"+a.get("id")+"/cancel",owner,map(),200);reserve(b,s,helper,200);assertEquals(1,list("/life/pickup",helper).size());}
    @Test void cancelledOrdersReleaseCapacityAndInvalidateCredentials()throws Exception{Map<String,Object>s=slot(1),o=order(owner);reserve(o,s,owner,200);String code=s(data(call("POST","/life/pickup/"+o.get("id")+"/credential",owner,map("delegate",false),200)),"code");o.put("status","cancelled");store.save("order",o);call("POST","/life/pickup/check",admin,map("code",code),409);reserve(order(helper),s,helper,200);}
    @Test void pickupCannotChangeSettlementAndRepeatedConfirmationIsIdempotent()throws Exception{Map<String,Object>s=slot(1),o=order(owner);reserve(o,s,owner,200);String code=s(data(call("POST","/life/pickup/"+o.get("id")+"/credential",owner,map("delegate",false),200)),"code");call("POST","/life/pickup/check",organizer,map("code",code),403);call("POST","/life/pickup/check",admin,map("code",code),200);assertEquals("ready",store.get("order",s(o,"id")).get("status"));call("POST","/life/pickup/check",admin,map("code",code,"confirm",true),200);call("POST","/life/pickup/check",admin,map("code",code,"confirm",true),200);assertEquals("completed",store.get("order",s(o,"id")).get("status"));assertEquals("unconfirmed",store.get("order",s(o,"id")).get("settlement"));}
    @Test void delegateCodeCanBeRevokedAndIsNotListed()throws Exception{Map<String,Object>s=slot(1),o=order(owner);reserve(o,s,owner,200);String path="/life/pickup/"+o.get("id")+"/credential";String code=s(data(call("POST",path,owner,map("delegate",true),200)),"code");String view=json.writeValueAsString(list("/life/pickup",owner));assertFalse(view.contains("Hash"));assertFalse(view.contains(code));call("POST",path,owner,map("delegate",true,"revoke",true),200);call("POST","/life/pickup/check",admin,map("code",code),404);}
    @Test void slotWithReservationCannotBeEditedOrClosed()throws Exception{Map<String,Object>s=slot(1);reserve(order(owner),s,owner,200);action(s,admin,"close",409);Map<String,Object>f=new LinkedHashMap<>(s);call("POST","/life/entries",admin,f,409);}
    @Test void simultaneousReservationsCannotOverbook()throws Exception{Map<String,Object>s=slot(1),a=order(owner),b=order(helper);ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch ready=new CountDownLatch(2),start=new CountDownLatch(1);List<Future<Integer>>tasks=new ArrayList<>();for(Map<String,Object>o:Arrays.asList(a,b)){Map<String,Object>who=o==a?owner:helper;tasks.add(pool.submit(()->{ready.countDown();start.await();return mvc.perform(post("/life/pickup/reserve").header("Authorization","Bearer "+who.get("token")).contentType("application/json").content(json.writeValueAsBytes(map("orderId",o.get("id"),"slotId",s.get("id"))))).andReturn().getResponse().getStatus();}));}try{assertTrue(ready.await(10,TimeUnit.SECONDS));start.countDown();List<Integer>codes=Arrays.asList(tasks.get(0).get(20,TimeUnit.SECONDS),tasks.get(1).get(20,TimeUnit.SECONDS));assertTrue(codes.contains(200));assertTrue(codes.contains(409));}finally{pool.shutdownNow();}}
    @Test void progressUsesVerifiedQuantitiesAndProtectsParent()throws Exception{String project=id();store.save("crowd_project",map("id",project,"title","验收共建","type","资金意向","unit","元","goal",100,"authorId",owner.get("id"),"status","approved"));store.save("crowd_pledge",map("id",id(),"projectId",project,"quantity",10,"status","pledged"));Map<String,Object>f=form("progress");f.putAll(map("referenceId",project,"milestone","执行进展","plannedOn",LocalDate.now().toString()));call("POST","/life/entries",helper,f,403);Map<String,Object>r=data(call("POST","/life/entries",owner,f,200));action(r,admin,"approve",200);Map<?,?>p=(Map<?,?>)entry(r,null).get("project");assertEquals(10,p.get("pledged"));assertEquals(0,p.get("delivered"));Map<String,Object>raw=store.get("crowd_project",project);raw.put("status","rejected");store.save("crowd_project",raw);call("GET","/life/entries/"+r.get("id"),helper,null,404);}
    @Test void meetingRequiresSignupAndHidesOtherMembers()throws Exception{String event=id();store.save("event",map("id",event,"title","验收活动","status","published","startsAt",Instant.now().plusSeconds(3600).toString(),"endsAt",Instant.now().plusSeconds(7200).toString()));Map<String,Object>f=form("trip");f.putAll(map("referenceId",event,"meeting","九点大厅集合","transport","乘坐公交到入口","contact","组织者同意公开的渠道","meetingPointsText","地铁出口\n大厅"));Map<String,Object>r=data(call("POST","/life/entries",admin,f,200));String path="/life/entries/"+r.get("id")+"/meeting";call("POST",path,owner,map("point","大厅"),409);store.save("signup",map("id",event+":"+owner.get("id"),"eventId",event,"userId",owner.get("id"),"status","registered"));call("POST",path,owner,map("point","大厅"),200);Map<String,Object>result=data(call("GET",path,helper,null,200));assertTrue(((List<?>)result.get("participants")).isEmpty());assertEquals(1,((Map<?,?>)result.get("counts")).get("大厅"));}
    @Test void imagesFollowApprovalAndRemoval()throws Exception{java.awt.image.BufferedImage image=new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_RGB);java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",bytes);String result=mvc.perform(multipart("/media/upload").file(new MockMultipartFile("file","test.png","image/png",bytes.toByteArray())).param("scope","life").header("Authorization","Bearer "+owner.get("token"))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();Map<String,Object>p=data(json.readValue(result,Map.class)),f=form("help");f.put("photos",Arrays.asList(p.get("id")));Map<String,Object>r=data(call("POST","/life/entries",owner,f,200));mvc.perform(get("/media/"+p.get("id"))).andExpect(status().isNotFound());action(r,admin,"approve",200);mvc.perform(get("/media/"+p.get("id"))).andExpect(status().isOk());f.putAll(map("id",r.get("id"),"revision",entry(r,owner).get("revision"),"photos",Collections.emptyList()));call("POST","/life/entries",owner,f,200);mvc.perform(get("/media/"+p.get("id"))).andExpect(status().isNotFound());}
    @Test void serviceWorkCenterSharesNoticeReadStateAndProtectsPrivateDetails()throws Exception{
        Map<String,Object>r=approvedHelp();apply(r,helper);
        Map<String,Object>target=data(call("GET","/work/target?kind=life_entry&id="+r.get("id"),helper,null,200));
        assertEquals("life",target.get("navigate"));
        call("GET","/work/target?kind=life_entry&id="+r.get("id"),other,null,404);
        Map<String,Object>notice=list("/life/notifications",owner).get(0);
        call("POST","/work/notices/"+notice.get("id")+"/read",other,map(),404);
        call("POST","/work/notices/"+notice.get("id")+"/read",owner,map(),200);
        assertTrue(b(store.get("business_notice",s(notice,"id")),"read"));
        assertTrue(list("/life/notifications",owner).stream().anyMatch(n->s(n,"id").equals(s(notice,"id"))&&b(n,"read")));
        Map<String,Object>f=new LinkedHashMap<>(entry(r,owner));f.put("title","审核中的未公开标题");call("POST","/life/entries",owner,f,200);
        Map<String,Object>hidden=data(call("GET","/work/target?kind=life_entry&id="+r.get("id"),helper,null,200));
        assertFalse(json.writeValueAsString(hidden).contains("审核中的未公开标题"));assertEquals("tasks",hidden.get("lifeTab"));
    }
    @Test void applicationCanBeWithdrawnDuringPublisherReview()throws Exception{
        Map<String,Object>r=approvedHelp(),app=apply(r,helper),f=new LinkedHashMap<>(entry(r,owner));
        f.put("content","发布者变更了内容，尚在等待审核。");call("POST","/life/entries",owner,f,200);
        call("GET","/life/entries/"+r.get("id"),helper,null,404);
        appAction(app,helper,"withdraw",200);assertEquals("withdrawn",store.get("life_application",s(app,"id")).get("status"));
    }

}
